import React, { createContext, useContext, Suspense, lazy } from 'react'

export const ModuleRegistryContext = createContext({ register: () => {} })

export function ModuleHost({ tenantId }) {
  const { getModuleLoader } = useContext(ModuleRegistryContext)
  const modules = ['ModuleA', 'ModuleB']
  return (
    <div>
